    title: "Streakboom: gặp Peak, chú mèo thú cưng cho màn hình Windows", nav_install: "Cài đặt", nav_privacy: "Riêng tư", nav_faq: "Hỏi đáp",
    hero_title: "Streakboom: gặp Peak, chú mèo nhỏ trên màn hình của bạn",
